ALTER TABLE open_sale_tabs ADD COLUMN business_id BIGINT UNSIGNED NULL AFTER id, ADD COLUMN branch_id BIGINT UNSIGNED NULL AFTER business_id, ADD COLUMN user_id BIGINT UNSIGNED NULL AFTER branch_id, ADD COLUMN public_id CHAR(36) NULL AFTER user_id, ADD COLUMN name VARCHAR(100) NOT NULL DEFAULT 'Venta abierta', ADD COLUMN customer_id BIGINT UNSIGNED NULL, ADD COLUMN payload_json LONGTEXT NULL, ADD COLUMN status ENUM('open','completed','cancelled') NOT NULL DEFAULT 'open', ADD COLUMN updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP;
CREATE UNIQUE INDEX uq_open_sale_public ON open_sale_tabs(public_id);
CREATE INDEX idx_open_sales_branch ON open_sale_tabs(business_id,branch_id,status,updated_at);